def burning_moscow(at=None):
    return [fire('Moscow', at, 'mf', size=1.6, n=5), fire('Moscow', at if at is None else (at, 0.3) if isinstance(at, str) else at,
                                                          'mf2', size=1.0, n=4, dx=-90, dy=30),
            fire('Moscow', at if at is None else (at, 0.6) if isinstance(at, str) else at, 'mf3', size=1.0, n=4, dx=100, dy=40)]

def row(kinds, at_words, y=0.42, s=110, labels=None, ids='row'):
    """icons in a row across the screen (screen space)"""
    n = len(kinds); out = []
    for i, k in enumerate(kinds):
        x = 0.5 + (i - (n - 1) / 2) * 0.16
        out.append(icon(k, ('s', x, y), at_words[i] if isinstance(at_words, list) else at_words, labels[i] if labels else None,
                        f'{ids}{i}', s=s, pill=False, ls=34))
    return out

